def _dec_in(value: object) -> Decimal:
    if isinstance(value, float):
        raise TypeError("a decimal is a str, an int or a Decimal, never a float")
    if isinstance(value, bool) or not isinstance(value, str | int | Decimal):
        raise TypeError(f"a decimal is a str, an int or a Decimal, not {type(value).__name__}")
    text = value if isinstance(value, str) else format(value, "f")
    if _DEC_PATTERN.fullmatch(text) is None:
        raise ValueError(f"{text!r} is not a canonical decimal")
    return Decimal(text)


